/* Model terminate function */
void IP02_FreqTest_terminate(void)
{
  /* Terminate for S-Function (hil_initialize_block): '<Root>/HIL Initialize' */

  /* S-Function Block: IP02_FreqTest/HIL Initialize (hil_initialize_block) */
  {
    t_boolean is_switching;
    t_int result;
    t_uint32 num_final_analog_outputs = 0;
    hil_task_stop_all(IP02_FreqTest_DW.HILInitialize_Card);
    hil_monitor_stop_all(IP02_FreqTest_DW.HILInitialize_Card);
    is_switching = false;
    if ((IP02_FreqTest_P.HILInitialize_AOTerminate && !is_switching) ||
        (IP02_FreqTest_P.HILInitialize_AOExit && is_switching)) {
      IP02_FreqTest_DW.HILInitialize_AOVoltages[0] =
        IP02_FreqTest_P.HILInitialize_AOFinal;
      IP02_FreqTest_DW.HILInitialize_AOVoltages[1] =
        IP02_FreqTest_P.HILInitialize_AOFinal;
      num_final_analog_outputs = 2U;
    } else {
      num_final_analog_outputs = 0;
    }

    if (num_final_analog_outputs > 0) {
      result = hil_write_analog(IP02_FreqTest_DW.HILInitialize_Card,
        IP02_FreqTest_P.HILInitialize_AOChannels, num_final_analog_outputs,
        &IP02_FreqTest_DW.HILInitialize_AOVoltages[0]);
      if (result < 0) {
        msg_get_error_messageA(NULL, result, _rt_error_message, sizeof
          (_rt_error_message));
        rtmSetErrorStatus(IP02_FreqTest_M, _rt_error_message);
      }
    }

    hil_task_delete_all(IP02_FreqTest_DW.HILInitialize_Card);
    hil_monitor_delete_all(IP02_FreqTest_DW.HILInitialize_Card);
    hil_close(IP02_FreqTest_DW.HILInitialize_Card);
    IP02_FreqTest_DW.HILInitialize_Card = NULL;
  }
}

