/* Registration function */
RT_MODEL_IP02_FreqTest_T *IP02_FreqTest(void)
{
  /* Registration code */

  /* initialize real-time model */
  (void) memset((void *)IP02_FreqTest_M, 0,
                sizeof(RT_MODEL_IP02_FreqTest_T));

  {
    /* Setup solver object */
    rtsiSetSimTimeStepPtr(&IP02_FreqTest_M->solverInfo,
                          &IP02_FreqTest_M->Timing.simTimeStep);
    rtsiSetTPtr(&IP02_FreqTest_M->solverInfo, &rtmGetTPtr(IP02_FreqTest_M));
    rtsiSetStepSizePtr(&IP02_FreqTest_M->solverInfo,
                       &IP02_FreqTest_M->Timing.stepSize0);
    rtsiSetdXPtr(&IP02_FreqTest_M->solverInfo, &IP02_FreqTest_M->derivs);
    rtsiSetContStatesPtr(&IP02_FreqTest_M->solverInfo, (real_T **)
                         &IP02_FreqTest_M->contStates);
    rtsiSetNumContStatesPtr(&IP02_FreqTest_M->solverInfo,
      &IP02_FreqTest_M->Sizes.numContStates);
    rtsiSetNumPeriodicContStatesPtr(&IP02_FreqTest_M->solverInfo,
      &IP02_FreqTest_M->Sizes.numPeriodicContStates);
    rtsiSetPeriodicContStateIndicesPtr(&IP02_FreqTest_M->solverInfo,
      &IP02_FreqTest_M->periodicContStateIndices);
    rtsiSetPeriodicContStateRangesPtr(&IP02_FreqTest_M->solverInfo,
      &IP02_FreqTest_M->periodicContStateRanges);
    rtsiSetContStateDisabledPtr(&IP02_FreqTest_M->solverInfo, (boolean_T**)
      &IP02_FreqTest_M->contStateDisabled);
    rtsiSetErrorStatusPtr(&IP02_FreqTest_M->solverInfo, (&rtmGetErrorStatus
      (IP02_FreqTest_M)));
    rtsiSetRTModelPtr(&IP02_FreqTest_M->solverInfo, IP02_FreqTest_M);
  }

  rtsiSetSimTimeStep(&IP02_FreqTest_M->solverInfo, MAJOR_TIME_STEP);
  rtsiSetIsMinorTimeStepWithModeChange(&IP02_FreqTest_M->solverInfo, false);
  rtsiSetIsContModeFrozen(&IP02_FreqTest_M->solverInfo, false);
  IP02_FreqTest_M->intgData.f[0] = IP02_FreqTest_M->odeF[0];
  IP02_FreqTest_M->contStates = ((real_T *) &IP02_FreqTest_X);
  IP02_FreqTest_M->contStateDisabled = ((boolean_T *) &IP02_FreqTest_XDis);
  IP02_FreqTest_M->Timing.tStart = (0.0);
  rtsiSetSolverData(&IP02_FreqTest_M->solverInfo, (void *)
                    &IP02_FreqTest_M->intgData);
  rtsiSetSolverName(&IP02_FreqTest_M->solverInfo,"ode1");

  /* Initialize timing info */
  {
    int_T *mdlTsMap = IP02_FreqTest_M->Timing.sampleTimeTaskIDArray;
    mdlTsMap[0] = 0;
    mdlTsMap[1] = 1;
    IP02_FreqTest_M->Timing.sampleTimeTaskIDPtr = (&mdlTsMap[0]);
    IP02_FreqTest_M->Timing.sampleTimes =
      (&IP02_FreqTest_M->Timing.sampleTimesArray[0]);
    IP02_FreqTest_M->Timing.offsetTimes =
      (&IP02_FreqTest_M->Timing.offsetTimesArray[0]);

    /* task periods */
    IP02_FreqTest_M->Timing.sampleTimes[0] = (0.0);
    IP02_FreqTest_M->Timing.sampleTimes[1] = (0.002);

    /* task offsets */
    IP02_FreqTest_M->Timing.offsetTimes[0] = (0.0);
    IP02_FreqTest_M->Timing.offsetTimes[1] = (0.0);
  }

  rtmSetTPtr(IP02_FreqTest_M, &IP02_FreqTest_M->Timing.tArray[0]);

  {
    int_T *mdlSampleHits = IP02_FreqTest_M->Timing.sampleHitArray;
    mdlSampleHits[0] = 1;
    mdlSampleHits[1] = 1;
    IP02_FreqTest_M->Timing.sampleHits = (&mdlSampleHits[0]);
  }

  rtmSetTFinal(IP02_FreqTest_M, 120.0);
  IP02_FreqTest_M->Timing.stepSize0 = 0.002;
  IP02_FreqTest_M->Timing.stepSize1 = 0.002;

  /* External mode info */
  IP02_FreqTest_M->Sizes.checksums[0] = (2259599495U);
  IP02_FreqTest_M->Sizes.checksums[1] = (4266447507U);
  IP02_FreqTest_M->Sizes.checksums[2] = (754829764U);
  IP02_FreqTest_M->Sizes.checksums[3] = (2181358916U);

  {
    static const sysRanDType rtAlwaysEnabled = SUBSYS_RAN_BC_ENABLE;
    static RTWExtModeInfo rt_ExtModeInfo;
    static const sysRanDType *systemRan[1];
    IP02_FreqTest_M->extModeInfo = (&rt_ExtModeInfo);
    rteiSetSubSystemActiveVectorAddresses(&rt_ExtModeInfo, systemRan);
    systemRan[0] = &rtAlwaysEnabled;
    rteiSetModelMappingInfoPtr(IP02_FreqTest_M->extModeInfo,
      &IP02_FreqTest_M->SpecialInfo.mappingInfo);
    rteiSetChecksumsPtr(IP02_FreqTest_M->extModeInfo,
                        IP02_FreqTest_M->Sizes.checksums);
    rteiSetTPtr(IP02_FreqTest_M->extModeInfo, rtmGetTPtr(IP02_FreqTest_M));
  }

  IP02_FreqTest_M->solverInfoPtr = (&IP02_FreqTest_M->solverInfo);
  IP02_FreqTest_M->Timing.stepSize = (0.002);
  rtsiSetFixedStepSize(&IP02_FreqTest_M->solverInfo, 0.002);
  rtsiSetSolverMode(&IP02_FreqTest_M->solverInfo, SOLVER_MODE_SINGLETASKING);

  /* block I/O */
  IP02_FreqTest_M->blockIO = ((void *) &IP02_FreqTest_B);
  (void) memset(((void *) &IP02_FreqTest_B), 0,
                sizeof(B_IP02_FreqTest_T));

  /* parameters */
  IP02_FreqTest_M->defaultParam = ((real_T *)&IP02_FreqTest_P);

  /* states (continuous) */
  {
    real_T *x = (real_T *) &IP02_FreqTest_X;
    IP02_FreqTest_M->contStates = (x);
    (void) memset((void *)&IP02_FreqTest_X, 0,
                  sizeof(X_IP02_FreqTest_T));
  }

  /* disabled states */
  {
    boolean_T *xdis = (boolean_T *) &IP02_FreqTest_XDis;
    IP02_FreqTest_M->contStateDisabled = (xdis);
    (void) memset((void *)&IP02_FreqTest_XDis, 0,
                  sizeof(XDis_IP02_FreqTest_T));
  }

  /* states (dwork) */
  IP02_FreqTest_M->dwork = ((void *) &IP02_FreqTest_DW);
  (void) memset((void *)&IP02_FreqTest_DW, 0,
                sizeof(DW_IP02_FreqTest_T));

  /* data type transition information */
  {
    static DataTypeTransInfo dtInfo;
    (void) memset((char_T *) &dtInfo, 0,
                  sizeof(dtInfo));
    IP02_FreqTest_M->SpecialInfo.mappingInfo = (&dtInfo);
    dtInfo.numDataTypes = 21;
    dtInfo.dataTypeSizes = &rtDataTypeSizes[0];
    dtInfo.dataTypeNames = &rtDataTypeNames[0];

    /* Block I/O transition table */
    dtInfo.BTransTable = &rtBTransTable;

    /* Parameters transition table */
    dtInfo.PTransTable = &rtPTransTable;
  }

  /* Initialize Sizes */
  IP02_FreqTest_M->Sizes.numContStates = (2);/* Number of continuous states */
  IP02_FreqTest_M->Sizes.numPeriodicContStates = (0);
                                      /* Number of periodic continuous states */
  IP02_FreqTest_M->Sizes.numY = (0);   /* Number of model outputs */
  IP02_FreqTest_M->Sizes.numU = (0);   /* Number of model inputs */
  IP02_FreqTest_M->Sizes.sysDirFeedThru = (0);/* The model is not direct feedthrough */
  IP02_FreqTest_M->Sizes.numSampTimes = (2);/* Number of sample times */
  IP02_FreqTest_M->Sizes.numBlocks = (12);/* Number of blocks */
  IP02_FreqTest_M->Sizes.numBlockIO = (6);/* Number of block outputs */
  IP02_FreqTest_M->Sizes.numBlockPrms = (100);/* Sum of parameter "widths" */
  return IP02_FreqTest_M;
}

